var i=`kiss-keep-it-simple`;var s=3;var o={en:[{id:`T003-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`KISS — Keep It Simple`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`DRY means every piece of knowledge should have one authoritative representation.`},{id:`B`,text:`KISS favors the simplest design that satisfies known requirements and foreseeable risks.`},{id:`C`,text:`SOLID groups five object-oriented design heuristics: single responsibility, open/closed, Liskov substitution, interface segregation, and dependency inversion.`},{id:`D`,text:`POLA says an interface should behave in ways its users reasonably expect.`}]},{id:`T003-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`KISS — Keep It Simple`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Prefer asking an object to perform an operation over traversing several objects and making decisions externally.`},{id:`B`,text:`SRP asks for one coherent reason to change; OCP prefers extension at stable variation points; LSP preserves behavioral contracts; ISP offers narrow consumer-oriented interfaces; DIP makes policy depend on abstractions rather than volatile implementations.`},{id:`C`,text:`Compare alternatives by number of components, states, exceptional paths, deployment steps, and cognitive overhead.`},{id:`D`,text:`Define boundaries around coherent policies and give each a narrow interface.`}]},{id:`T003-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`For an internal dashboard serving twenty people, one Node.js service and a relational database may be more robust than several services, a queue, and service discovery.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Move the authoritative calculation server-side and expose a stable contract; client-side previews should be treated as provisional, not a competing source of truth.`},{id:`B`,text:`Define what happens on insufficient funds and ensure the operation is atomic.`},{id:`C`,text:`It should still store currency explicitly if changing that later would corrupt historical amounts.`},{id:`D`,text:`Write down which future signals would justify changing that choice.`}]},{id:`T003-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`KISS — Keep It Simple`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Simplistic is not simple: ignoring authorization, error handling, or transaction boundaries creates hidden complexity.`},{id:`B`,text:`Different audiences have different expectations; conventions can evolve.`},{id:`C`,text:`Zero coupling is impossible and sometimes undesirable.`},{id:`D`,text:`Blind wrapper methods lead to pass-through classes and anemic models.`}]},{id:`T003-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`Simplicity means lower conceptual load and fewer moving parts, not necessarily fewer lines or the absence of safeguards.`}]}]},{id:`T003-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`The shortest implementation is always the simplest, even without error handling.`}]}]},{id:`T003-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Conversely, 'enterprise-ready' scaffolding can impose costs without delivering value.`}]}]},{id:`T003-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`KISS — Keep It Simple`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Compare alternatives by number of components, states, exceptional paths, deployment steps, and cognitive overhead.`},{id:`B`,text:`KISS justifies skipping transaction boundaries when they complicate code.`},{id:`C`,text:`SOLID requires an interface for every class, even when there is no variation.`},{id:`D`,text:`KISS favors the simplest design that satisfies known requirements and foreseeable risks.`}]},{id:`T003-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`KISS — Keep It Simple`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Write down which future signals would justify changing that choice.`},{id:`B`,text:`The shortest implementation is always the simplest, even without error handling.`},{id:`C`,text:`Liskov substitution concerns method signatures but not observable behavior.`},{id:`D`,text:`Conversely, 'enterprise-ready' scaffolding can impose costs without delivering value.`}]},{id:`T003-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`For an internal dashboard serving twenty people, one Node.js service and a relational database may be more robust than several services, a queue, and service discovery.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Map dependencies for a booking feature, identify two cohesion violations and two coupling hotspots, and propose boundaries with measurable effects on regression tests.`},{id:`B`,text:`Design an MVP notification feature with no speculative queue. Ask the agent to enumerate failure modes, choose the minimum defensible architecture, and document triggers for scaling later.`},{id:`C`,text:`Review a service with deep property chains, identify which leak implementation structure, and refactor only the chains that cross ownership boundaries. Add regression tests.`},{id:`D`,text:`Audit a REST API and UI for misleading names and hidden side effects. Propose consistent behavior, write examples of expected error responses, and test retry semantics.`}]},{id:`T003-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`How can you prove a shorter solution is genuinely simpler to maintain?`}]}]},{id:`T003-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`For an internal dashboard serving twenty people, one Node.js service and a relational database may be more robust than several services, a queue, and service discovery.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`KISS — Keep It Simple`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T003-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`For an internal dashboard serving twenty people, one Node.js service and a relational database may be more robust than several services, a queue, and service discovery.`,b:!0},{t:` — propose three checks for `},{t:`KISS — Keep It Simple`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T003-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`For an internal dashboard serving twenty people, one Node.js service and a relational database may be more robust than several services, a queue, and service discovery.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T003-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`KISS — Keep It Simple`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`For an internal dashboard serving twenty people, one Node.js service and a relational database may be more robust than several services, a queue, and service discovery.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T003-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`KISS — зберігай простоту`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`DRY означає, що кожне правило або знання має одне авторитетне представлення.`},{id:`B`,text:`KISS віддає перевагу найпростішому дизайну, який виконує відомі вимоги та враховує реальні ризики.`},{id:`C`,text:`SOLID об’єднує п’ять принципів об’єктного проєктування: єдину відповідальність, відкритість/закритість, підстановку Лісков, розділення інтерфейсів та інверсію залежностей.`},{id:`D`,text:`POLA означає, що інтерфейс має поводитися так, як користувач обґрунтовано очікує.`}]},{id:`T003-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`KISS — зберігай простоту`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Краще просити об’єкт виконати дію, ніж проходити кілька вкладених об’єктів та ухвалювати рішення ззовні.`},{id:`B`,text:`SRP вимагає однієї узгодженої причини змін; OCP дозволяє розширення в точках варіативності; LSP зберігає поведінкові контракти; ISP пропонує вузькі інтерфейси; DIP відділяє політику від мінливих реалізацій.`},{id:`C`,text:`Порівнюйте варіанти за кількістю компонентів, станів, виняткових шляхів, кроків розгортання та когнітивним навантаженням.`},{id:`D`,text:`Проводьте межі навколо узгоджених політик і надавайте вузькі інтерфейси.`}]},{id:`T003-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Для внутрішньої панелі на двадцять користувачів один Node.js-сервіс і реляційна БД можуть бути надійнішими за мікросервіси, чергу й service discovery.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Перенесіть авторитетний розрахунок на сервер і надайте контракт; попередній розрахунок у клієнті вважайте орієнтовним.`},{id:`B`,text:`Визначте поведінку за браку коштів і забезпечте атомарність операції.`},{id:`C`,text:`Але валюту варто зберігати явно, якщо інакше майбутні зміни пошкодять історичні суми.`},{id:`D`,text:`Зафіксуйте сигнали, які виправдають ускладнення.`}]},{id:`T003-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`KISS — зберігай простоту`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Примітивність не дорівнює простоті: ігнорування авторизації, помилок чи транзакцій ховає складність.`},{id:`B`,text:`Різні аудиторії мають різні очікування, а конвенції змінюються.`},{id:`C`,text:`Нульова зв’язність неможлива, а часом і небажана.`},{id:`D`,text:`Сліпі методи-обгортки створюють класи-посередники без сенсу.`}]},{id:`T003-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Простота — це менше понять і рухомих частин, а не обов’язково менше рядків або відсутність захисту.`}]}]},{id:`T003-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Найкоротша реалізація завжди найпростіша, навіть без обробки помилок.`}]}]},{id:`T003-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Водночас «enterprise-ready» каркас може створити витрати без користі.`}]}]},{id:`T003-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`KISS — зберігай простоту`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Порівнюйте варіанти за кількістю компонентів, станів, виняткових шляхів, кроків розгортання та когнітивним навантаженням.`},{id:`B`,text:`KISS виправдовує пропуск меж транзакцій, якщо вони ускладнюють код.`},{id:`C`,text:`SOLID вимагає інтерфейсу для кожного класу, навіть якщо немає варіативності.`},{id:`D`,text:`KISS віддає перевагу найпростішому дизайну, який виконує відомі вимоги та враховує реальні ризики.`}]},{id:`T003-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`KISS — зберігай простоту`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Зафіксуйте сигнали, які виправдають ускладнення.`},{id:`B`,text:`Найкоротша реалізація завжди найпростіша, навіть без обробки помилок.`},{id:`C`,text:`Підстановка Лісков стосується сигнатур методів, а не спостережуваної поведінки.`},{id:`D`,text:`Водночас «enterprise-ready» каркас може створити витрати без користі.`}]},{id:`T003-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Для внутрішньої панелі на двадцять користувачів один Node.js-сервіс і реляційна БД можуть бути надійнішими за мікросервіси, чергу й service discovery.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Намалюйте залежності фічі бронювання, знайдіть дві проблеми згуртованості та дві проблеми зв’язності й запропонуйте межі з вимірюваним ефектом для тестів.`},{id:`B`,text:`Спроєктуйте MVP-сповіщення без гіпотетичної черги. Попросіть агента перелічити збої, обрати мінімально достатню архітектуру й визначити умови майбутнього масштабування.`},{id:`C`,text:`Перегляньте сервіс із довгими ланцюжками властивостей, знайдіть витоки внутрішньої структури та змініть лише ті, що перетинають межі власності. Додайте регресійні тести.`},{id:`D`,text:`Перевірте REST API та UI на оманливі назви й приховані побічні ефекти. Запропонуйте узгоджену поведінку, приклади помилок і тести повторних запитів.`}]},{id:`T003-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Як довести, що коротше рішення справді простіше підтримувати?`}]}]},{id:`T003-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Для внутрішньої панелі на двадцять користувачів один Node.js-сервіс і реляційна БД можуть бути надійнішими за мікросервіси, чергу й service discovery.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`KISS — зберігай простоту`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T003-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Для внутрішньої панелі на двадцять користувачів один Node.js-сервіс і реляційна БД можуть бути надійнішими за мікросервіси, чергу й service discovery.`,b:!0},{t:` запропонуйте три перевірки `},{t:`KISS — зберігай простоту`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T003-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Для внутрішньої панелі на двадцять користувачів один Node.js-сервіс і реляційна БД можуть бути надійнішими за мікросервіси, чергу й service discovery.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T003-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`KISS — зберігай простоту`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Для внутрішньої панелі на двадцять користувачів один Node.js-сервіс і реляційна БД можуть бути надійнішими за мікросервіси, чергу й service discovery.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var n={slug:i,topicId:3,questions:o};export{n as default,o as questions,i as slug,s as topicId};